import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, PointLight, DoubleSide } from 'three/webgpu';
import { uv, mix, smoothstep, color, vec2, vec3, sin, fract, dot } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.name = 'hub-collection-card-1-label';

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // --- 1. Card backdrop: engineered gradient plaque with subtle procedural grain ---
  const panelW = 1.4;
  const panelH = 0.5;
  const panelGeo = new PlaneGeometry(panelW, panelH, 1, 1);

  const gradTop = color(colors.ink);
  const gradBottom = color(colors.surface);
  const gradientFactor = smoothstep(0.0, 1.0, uv().y);

  const grainUv = uv().mul(340.0);
  const noiseSeed = dot(grainUv, vec2(12.9898, 78.233));
  const noise = fract(sin(noiseSeed).mul(43758.5453));
  const grain = noise.sub(0.5).mul(0.045);

  const panelMat = new MeshStandardNodeMaterial();
  panelMat.colorNode = mix(gradBottom, gradTop, gradientFactor).add(vec3(grain, grain, grain));
  panelMat.roughness = 0.58;
  panelMat.metalness = 0.4;
  panelMat.clearcoat = 0.15;
  panelMat.clearcoatRoughness = 0.32;
  panelMat.side = DoubleSide;

  const panel = new Mesh(panelGeo, panelMat);
  panel.position.set(0, 0, 0);
  group.add(panel);

  // --- 2. Floating accent decorative image (from atlas region 0,0,512,320 -> aspect 1.6) ---
  const accentAspect = 512 / 320;
  const accentH = 0.3;
  const accentW = accentH * accentAspect;
  const accentGeo = new PlaneGeometry(accentW, accentH, 1, 1);
  const accentMat = new MeshBasicNodeMaterial();
  accentMat.transparent = true;
  accentMat.opacity = 0.85;
  accentMat.depthWrite = false;

  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(panelW * 0.5 - accentW * 0.5 - 0.08, 0, 0.015);
  group.add(accentMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      accentMat.map = tex;
      accentMat.needsUpdate = true;
    });
  }

  // --- 3. Headline text: "Collection 1" ---
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [{ text: 'Collection 1', role: 'headline', typography: { fontSize: 39 } }];

  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const fontSize = headlineItem?.typography?.fontSize ?? 39;

  const headline = ctx.fontAtlas.createText(headlineItem?.text ?? 'Collection 1', {
    fontSize,
    color: colors.paper,
    align: 'left',
  });
  headline.position.set(-panelW * 0.5 + 0.12, -0.02, 0.02);
  group.add(headline);

  // --- 4. Accent underline (signal red) ---
  const underlineGeo = new PlaneGeometry(0.46, 0.02, 1, 1);
  const underlineMat = new MeshStandardNodeMaterial();
  underlineMat.colorNode = color(colors.accent);
  underlineMat.roughness = 0.5;
  underlineMat.metalness = 0.3;
  const underline = new Mesh(underlineGeo, underlineMat);
  underline.position.set(-panelW * 0.5 + 0.12 + 0.23, -0.14, 0.02);
  group.add(underline);

  // --- Local rim light carrying accent hue (small, cheap, node-local per doctrine) ---
  const rimLight = new PointLight(colors.accent, 0.9, 3.0);
  rimLight.position.set(0.6, 0.3, 0.8);
  group.add(rimLight);

  // --- Weighted-settle entrance (no perpetual motion; single settle transform) ---
  group.scale.setScalar(0.001);
  const tl = gsap.timeline();
  tl.to(group.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.55,
    ease: 'power3.out',
  }).to(group.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.35,
    ease: 'power4.out',
  });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose && m.dispose());
        } else if (obj.material.dispose) {
          obj.material.dispose();
        }
      }
    });
    if (rimLight.parent) rimLight.parent.remove(rimLight);
  };

  return group;
}
